-- Moderator management + live-stream moderation.
--
-- Backfills the migration that commits 467417f and 5116c70 changed the schema
-- without writing. Generated by diffing the schema at a8b59e0 (the last commit
-- where schema and migrations agreed) against HEAD.
--
-- Two statements from that raw diff were removed on purpose, because earlier
-- hand-written migrations already applied them to the database while leaving
-- the schema files behind:
--
--   ALTER TYPE "NotificationType" ADD VALUE 'MODERATOR_DEVICE_CHANGE_REQUESTED'  -> 20260816070000
--   ALTER TABLE "audit_logs" ADD COLUMN "violationReason"    -> 20260816080000
--
-- Re-issuing either would abort the deploy ("enum label already exists" /
-- "column already exists"). What remains matches the CI drift report exactly.

-- CreateEnum
CREATE TYPE "LiveStreamModerationMuteType" AS ENUM ('TEMPORARY', 'PERMANENT');

-- CreateEnum
