-- CreateEnum
CREATE TYPE "LiveStreamReportStatus" AS ENUM ('PENDING', 'REVIEWED', 'DISMISSED', 'ACTIONED');

-- CreateEnum
CREATE TYPE "ModerationApprovalRoomType" AS ENUM ('AUDIO_ROOM', 'VIDEO_ROOM', 'LIVE_STREAM');

-- CreateEnum
CREATE TYPE "ModerationApprovalStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');

-- AlterEnum
-- This migration adds more than one value to an enum.
-- With PostgreSQL versions 11 and earlier, this is not possible
-- in a single migration. This can be worked around by creating
-- multiple migrations, each migration adding only one value to
-- the enum.


ALTER TYPE "NotificationType" ADD VALUE 'MODERATION_CASE_ESCALATED';

